public class UserSessionCache {
    private static final Map<String, UserSession> cache = new HashMap<>();

    public void put(String userId, UserSession session) {
        cache.put(userId, session);  // Line 45 - from stack trace
    }

    public UserSession get(String userId) {
        return cache.get(userId);
    }

    public int size() {
        return cache.size();
    }
}

